import{_t as e,it as t,n,ot as r,rt as i,xt as a}from"./chunks/framework.C5Z6qjff.js";var o=JSON.parse(`{"title":"Logging in","description":"","frontmatter":{"title":"Logging in","covers":{"screens":["SCR-001","SCR-003","SCR-004","SCR-005"],"stories":["US-001","US-005","US-006","US-010","US-011","US-021","US-023","US-024","US-025","US-026","US-027","US-029","US-030"]}},"headers":[],"relativePath":"usage/login.md","filePath":"usage/login.md"}`),s={name:`usage/login.md`};function c(n,o,s,c,l,u){let d=a(`Screenshot`);return e(),i(`div`,null,[o[0]||=t(`<h1 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to “Logging in”">​</a></h1><p>Open the web interface and choose <em>Log in</em>. The page <em>Log in to OEA</em> offers one button <em>Log in with …</em> per identity provider of your organization and, below it, the login with the local system admin account.</p><h2 id="log-in-through-your-identity-provider" tabindex="-1">Log in through your identity provider <a class="header-anchor" href="#log-in-through-your-identity-provider" aria-label="Permalink to “Log in through your identity provider”">​</a></h2><ol><li>Choose <em>Log in with</em> and the name of your provider.</li><li>Log in at your provider as usual; it sends you back to OEA.</li><li>You are logged in. The header shows <em>Catalogs</em>, your profile and <em>Log out</em>.</li></ol><p>Your administrator must have created your person and bound it to your identity at the provider. If that is not the case, the login page shows <em>Login failed</em> – for safety, without the exact reason; your administrator finds it in the audit log. If the provider is not reachable, the page asks you to try again later.</p><p>Your roles come from your groups at the provider. Roles with administrative permissions apply only if you logged in with a second factor at the provider.</p><h2 id="log-in-with-the-local-system-admin-account" tabindex="-1">Log in with the local system admin account <a class="header-anchor" href="#log-in-with-the-local-system-admin-account" aria-label="Permalink to “Log in with the local system admin account”">​</a></h2><p>Enter the login name and password of the system admin account and choose <em>Log in</em>. After the setup phase, the page asks for the code of your authenticator app: enter it and choose <em>Confirm</em>. <em>Start again</em> returns to the password step.</p>`,8),r(d,{name:`login`,alt:`Login page with the providers and the login of the local system admin account`}),o[1]||=t(`<ul><li>After five wrong codes, you have to start again with the password.</li><li>After repeated wrong passwords, further attempts are delayed (at most 15 minutes).</li><li>Every login and every failed attempt – through a provider or with the local account – is recorded in the audit log with time, mechanism and result (<code>auth.login</code>, <code>auth.login-failed</code>); a failed attempt names the internal reason only there.</li></ul><h2 id="log-in-with-your-e-mail-address-and-password" tabindex="-1">Log in with your e-mail address and password <a class="header-anchor" href="#log-in-with-your-e-mail-address-and-password" aria-label="Permalink to “Log in with your e-mail address and password”">​</a></h2><p>If your organization runs OEA without an identity provider, your administrator gives you an initial password. Enter your e-mail address and this password in the local form of the login page.</p><ol><li>After the first login, the page <em>Change password</em> opens. Enter the initial password as current password and choose your own password twice. Until then, nothing else is available.</li><li>From then on, log in with your e-mail address and your own password. You can change it again under <code>/me/password</code>; this ends your other sessions.</li></ol><ul><li>Your password must meet the password policy of your organization: at least 12 characters, and possibly a longer minimum, certain character types, or a password you have not used recently. If it does not, the page lists every rule it misses.</li><li><em>Suggest a password</em> shows a generated password that meets the policy. Store it in your password manager, then use it with <em>Use as new password</em>. OEA does not keep the suggestion.</li><li>If your organization lets passwords expire, the page <em>Change password</em> opens at the first login after the expiry, as after an initial password.</li><li>The initial password expires after the time your administrator chose (default 72 hours). An expired initial password fails like a wrong one; ask your administrator for a new one.</li><li>If you forgot your password, your administrator resets it and gives you a temporary password. Your old password and all your sessions end at once; at the next login, you choose a new password.</li><li>A failed login never tells whether the account exists, and every failed attempt takes the same time.</li><li>Roles with administrative permissions need a second factor. They apply only after a login with password and code from your authenticator app (see <a href="#set-up-a-second-factor">Set up a second factor</a>).</li><li>If you have set up an authenticator app, the login asks for its code after the password. A wrong code fails like a wrong password; after five wrong codes, start again with the password.</li></ul><h2 id="your-profile" tabindex="-1">Your profile <a class="header-anchor" href="#your-profile" aria-label="Permalink to “Your profile”">​</a></h2><p><em>Profile</em> (<code>/me</code>) shows your name, the account type, whether your session is confirmed with a second factor, your roles and your authenticator apps. If no role is assigned to you yet, the profile tells you so; ask an administrator for access.</p><h2 id="set-up-a-second-factor" tabindex="-1">Set up a second factor <a class="header-anchor" href="#set-up-a-second-factor" aria-label="Permalink to “Set up a second factor”">​</a></h2><p>A second factor is an authenticator app (any app for time-based one-time passwords, TOTP) on your phone. The local system admin account needs one to end the setup phase (see <a href="./../setup/first-administrator">First administrator</a>). If you log in with your e-mail address and password, OEA offers it after the login as long as you have none; choose <em>Skip for now</em> to set it up later.</p><ol><li>In <em>Profile</em>, choose <em>Set up a second factor</em> (or <em>Add an authenticator app</em>). Optionally, give it a name, for example the device; without a name it is called &quot;Authenticator app&quot; with the date.</li><li>Choose <em>Set up authenticator app</em> and scan the QR code with the app.</li><li>Enter the code from the app under <em>Code from the app</em> and choose <em>Confirm</em>.</li></ol>`,10),r(d,{name:`second-factor-enroll`,alt:`Setting up the authenticator app with QR code and code field`}),o[2]||=t(`<p>The page confirms that the authenticator app is set up and the session is confirmed. Setting up a second factor needs a login within the last 5 minutes; otherwise, the page asks you to log in again.</p><ul><li>You can set up several authenticator apps, for example one on a backup phone. At the login, a code of any of them works.</li><li><em>Profile</em> lists your authenticator apps with the date they were added and last used. <em>Remove</em> takes one away, for example of a lost phone; this also needs a login within the last 5 minutes and ends your other sessions. The local system admin account keeps at least one after the setup phase.</li><li>If you lost every device, your administrator resets your second factors. You then log in with your password alone and set up a new authenticator app.</li></ul><h2 id="sessions-and-logging-out" tabindex="-1">Sessions and logging out <a class="header-anchor" href="#sessions-and-logging-out" aria-label="Permalink to “Sessions and logging out”">​</a></h2><p>Choose <em>Log out</em> in the header or in your profile. A session also ends after 30 minutes without activity and at the latest 12 hours after the login.</p>`,4)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};